import xml.etree.ElementTree as ET

NS = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
}

tree = ET.parse('/work/output/artifacts/skill-bpmn-author-validate/InvoiceApproval.bpmn')
root = tree.getroot()

errors = []

# 1. Root is definitions with BPMN namespace
assert 'definitions' in root.tag, "Root must be definitions"

# Collect all IDs declared in process
proc = root.find('bpmn:process', NS)
all_ids = {e.get('id') for e in proc.iter() if e.get('id')}
all_ids.add(proc.get('id'))

# 2. Check diagram: shape per node, edge per flow
plane = root.find('.//bpmndi:BPMNPlane', NS)
shapes = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', NS)}
edges  = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', NS)}

flow_nodes = []
seq_flows = []
for e in proc:
    tag = e.tag.split('}')[1] if '}' in e.tag else e.tag
    eid = e.get('id')
    if tag in ('startEvent','endEvent','exclusiveGateway','task','scriptTask',
               'serviceTask','userTask','subProcess','callActivity'):
        flow_nodes.append(eid)
    elif tag == 'sequenceFlow':
        seq_flows.append(eid)

for n in flow_nodes:
    if n not in shapes:
        errors.append(f"MISSING SHAPE for node {n}")
for f in seq_flows:
    if f not in edges:
        errors.append(f"MISSING EDGE for flow {f}")

# 3. Every sourceRef/targetRef resolves
for sf in proc.findall('bpmn:sequenceFlow', NS):
    for attr in ('sourceRef', 'targetRef'):
        ref = sf.get(attr)
        if ref not in all_ids:
            errors.append(f"Unresolved {attr}={ref} in {sf.get('id')}")

# 4. XOR gateway: non-default flows have conditions; exactly one default
for gw in proc.findall('bpmn:exclusiveGateway', NS):
    default = gw.get('default')
    outgoing = [o.text for o in gw.findall('bpmn:outgoing', NS)]
    if not default:
        errors.append(f"ExclusiveGateway {gw.get('id')} has no default flow")
    cond_flows = [sf.get('id') for sf in proc.findall('bpmn:sequenceFlow', NS)
                  if sf.get('id') in outgoing and sf.get('id') != default]
    for fid in cond_flows:
        sf = next(s for s in proc.findall('bpmn:sequenceFlow', NS) if s.get('id')==fid)
        cond = sf.find('bpmn:conditionExpression', NS)
        if cond is None:
            errors.append(f"Flow {fid} from XOR gateway {gw.get('id')} missing conditionExpression")

# 5. No activity/event with more than one incoming
for n in proc:
    tag = n.tag.split('}')[1] if '}' in n.tag else n.tag
    inc = n.findall('bpmn:incoming', NS)
    if len(inc) > 1:
        errors.append(f"FAKE_JOIN: {n.get('id')} ({tag}) has {len(inc)} incoming flows")

# 6. Check superfluous gateway (1 in, 1 out)
for gw in proc.findall('bpmn:exclusiveGateway', NS):
    inc  = len(gw.findall('bpmn:incoming', NS))
    out  = len(gw.findall('bpmn:outgoing', NS))
    if inc == 1 and out == 1:
        errors.append(f"SUPERFLUOUS_GATEWAY: {gw.get('id')}")

if errors:
    for e in errors:
        print("ERROR:", e)
else:
    print("Structural checklist: PASS — all rules satisfied")
EOF
